using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace ApiMcpServer.Tools;

/// <summary>
/// MCP tools that wrap the JSONPlaceholder REST API.
/// Uses constructor injection — IHttpClientFactory and ILogger are resolved by the
/// MCP SDK's DI pipeline and never appear in the tool schema sent to LLMs.
/// </summary>
[McpServerToolType]
public class PostTools(IHttpClientFactory httpFactory, ILogger<PostTools> logger)
{
    [McpServerTool, Description("Get a blog post by its numeric ID.")]
    public async Task<string> GetPost(
        [Description("The post ID (1–100)")] int id,
        CancellationToken cancellationToken = default)
    {
        var client = httpFactory.CreateClient("api");
        var post = await client.GetFromJsonAsync<Post>($"/posts/{id}", cancellationToken);
        return post is null
            ? "Post not found."
            : $"[{post.Id}] {post.Title}\n\n{post.Body}";
    }

    [McpServerTool, Description("Search posts by user ID.")]
    public async Task<string> GetPostsByUser(
        [Description("The user ID to filter by")] int userId,
        CancellationToken cancellationToken = default)
    {
        var client = httpFactory.CreateClient("api");
        var posts = await client.GetFromJsonAsync<Post[]>(
            $"/posts?userId={userId}", cancellationToken);

        if (posts is null || posts.Length == 0)
            return "No posts found for that user.";

        return string.Join("\n", posts.Select(p => $"• [{p.Id}] {p.Title}"));
    }

    [McpServerTool, Description("Create a new blog post.")]
    public async Task<string> CreatePost(
        [Description("Title of the new post")] string title,
        [Description("Body content of the post")] string body,
        [Description("Author user ID")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating post for user {UserId}", userId);

        var client = httpFactory.CreateClient("api");
        var response = await client.PostAsJsonAsync("/posts",
            new { title, body, userId }, cancellationToken);

        response.EnsureSuccessStatusCode();
        var created = await response.Content.ReadFromJsonAsync<Post>(cancellationToken);
        return $"Created post with ID {created?.Id}.";
    }
}

public record Post
{
    [JsonPropertyName("id")]     public int Id { get; init; }
    [JsonPropertyName("userId")] public int UserId { get; init; }
    [JsonPropertyName("title")]  public string Title { get; init; } = "";
    [JsonPropertyName("body")]   public string Body { get; init; } = "";
}

